  ts: 'typescript',
  tsx: 'typescript',
  mts: 'typescript',
  cts: 'typescript',
  py: 'python',
  py3: 'python',
  python3: 'python',
  ipython: 'python',
  gyp: 'python',
  pycon: 'python',
  rb: 'ruby',
  gemspec: 'ruby',
  podspec: 'ruby',
  yml: 'yaml',
  sh: 'bash',
  shell: 'bash',
  zsh: 'bash',
  console: 'bash',
  golang: 'go',
  rs: 'rust',
  kt: 'kotlin',
  kts: 'kotlin',
  cs: 'csharp',
  'c#': 'csharp',
  'c++': 'cpp',
  cpp: 'cpp',
  hpp: 'cpp',
  'h++': 'cpp',
  hh: 'cpp',
  cc: 'cpp',
  objc: 'objectivec',
  'obj-c': 'objectivec',
  bat: 'dos',
  cmd: 'dos',
  dos: 'dos',
  ps1: 'powershell',
  powershell: 'powershell',
  patch: 'diff',
  md: 'markdown',
